package com.appcore.runtime

/**
 * JVM test for L06 ReaResStrings (runtime-decrypt helper).
 *
 * Usage:
 *   java -cp resstrings-test.jar:<stdlib> \
 *     com.appcore.runtime.ReaResStringsTestKt \
 *     <res_strings.json> <resourceName> <expectedPlain> <tampered.json>
 *
 * The JSON files are generated by the test driver with
 * transformer/crypto.py (same blob format as the CLI), so this is a
 * cross-language round-trip: Python encrypt -> Kotlin decrypt.
 * Checks:
 *   1. loadFromJson loads the entry; decryptResource(name) == expected.
 *   2. placeholder()/isPlaceholder() round-trip.
 *   3. Tampered JSON (blob first char flipped) -> decrypt throws
 *      IllegalStateException, never a wrong value.
 *   4. Unknown name -> IllegalStateException.
 * Any failure exits non-zero. Prints TEST-PASS on success.
 */
fun main(args: Array<String>) {
    fun fail(msg: String): Nothing {
        println("FAIL: $msg")
        kotlin.system.exitProcess(1)
    }
    require(args.size == 4) {
        "usage: ReaResStringsTestKt <res_strings.json> <name> " +
            "<expectedPlain> <tampered.json>"
    }
    val (jsonPath, name, expected, tamperedPath) = args

    val json = java.io.File(jsonPath).readText(Charsets.UTF_8)
    val loaded = ReaResStrings.loadFromJson(json)
    if (loaded < 1) fail("loadFromJson loaded $loaded entries, want >= 1")
    if (name !in ReaResStrings.registeredNames()) {
        fail("registered names ${ReaResStrings.registeredNames()} lack $name")
    }
    println("LOAD-OK: $loaded entries, incl. $name")

    val plain = ReaResStrings.decryptResource(name)
    if (plain != expected) {
        fail("decryptResource returned [$plain], want [$expected]")
    }
    println("DECRYPT-OK: $plain")

    if (!ReaResStrings.isPlaceholder(ReaResStrings.placeholder(name))) {
        fail("placeholder() not recognised by isPlaceholder()")
    }
    if (ReaResStrings.isPlaceholder(expected)) {
        fail("real plaintext misread as a placeholder")
    }
    println("PLACEHOLDER-OK: ${ReaResStrings.placeholder(name)}")

    // Tampered blob must refuse.
    ReaResStrings.clear()
    val tamperedJson = java.io.File(tamperedPath).readText(Charsets.UTF_8)
    ReaResStrings.loadFromJson(tamperedJson)
    try {
        val bad = ReaResStrings.decryptResource(name)
        fail("tampered resource NOT refused, decrypt returned [$bad]")
    } catch (e: IllegalStateException) {
        println("TAMPER-REFUSED: ${e.message}")
    }

    // Unknown name must refuse.
    ReaResStrings.clear()
    ReaResStrings.loadFromJson(json)
    try {
        ReaResStrings.decryptResource("no_such_resource")
        fail("unknown resource name NOT refused")
    } catch (e: IllegalStateException) {
        println("UNKNOWN-REFUSED: ${e.message}")
    }

    println("TEST-PASS")
}
